        $bomCode='BOM-PLAN-'.$item['sku'];$pdo->prepare("INSERT INTO bills_of_material (bom_code,output_item_id,name,is_active,created_by) VALUES (:code,:item,:name,1,:user) ON DUPLICATE KEY UPDATE name=VALUES(name),is_active=1")->execute(['code'=>$bomCode,'item'=>$item['id'],'name'=>'Lista completa · '.$item['name'],'user'=>$user['id']]);$bom=findOne($pdo,"SELECT id FROM bills_of_material WHERE bom_code=:code FOR UPDATE",['code'=>$bomCode],'No se pudo preparar la lista completa.');
