        if($current&&$current['effective_from']===$effective){$pdo->prepare("UPDATE finished_product_bom_assignments SET oil_formula_version_id=:formula,compiled_bom_version_id=:compiled,assignment_status='ACTIVE',change_reason=:reason,created_by=:user WHERE id=:id")->execute(['formula'=>$formula['id'],'compiled'=>$compiled,'reason'=>$reason,'user'=>$user['id'],'id'=>$current['id']]);$assignment=(int)$current['id'];}
        else{if($current)$pdo->prepare("UPDATE finished_product_bom_assignments SET effective_to=DATE_SUB(:effective,INTERVAL 1 DAY),assignment_status='OBSOLETE' WHERE id=:id")->execute(['effective'=>$effective,'id'=>$current['id']]);$pdo->prepare("INSERT INTO finished_product_bom_assignments (finished_item_id,packaging_bom_version_id,oil_formula_version_id,compiled_bom_version_id,effective_from,assignment_status,change_reason,created_by) VALUES (:item,:packaging,:formula,:compiled,:effective,'ACTIVE',:reason,:user)")->execute(['item'=>$item['id'],'packaging'=>$packagingVersion,'formula'=>$formula['id'],'compiled'=>$compiled,'effective'=>$effective,'reason'=>$reason,'user'=>$user['id']]);$assignment=(int)$pdo->lastInsertId();}
