function changePackagingComponentV18(PDO $pdo,array $user,array $payload): array
{
    requirePermission($pdo,(int)$user['id'],'BOM_MANAGEMENT','UPDATE');$item=findOne($pdo,"SELECT id,sku,name FROM items WHERE id=:id AND item_type='FINISHED_GOOD' AND is_active=1",['id'=>(int)($payload['finished_item_id']??0)],'Selecciona un producto terminado oficial.');$component=findOne($pdo,"SELECT id,sku,name,base_uom_id FROM items WHERE id=:id AND item_type='PACKAGING' AND is_active=1",['id'=>(int)($payload['component_item_id']??0)],'Selecciona un material de empaque oficial.');$qty=positiveNumber($payload,'component_quantity','La cantidad por botella');$effective=validDate((string)($payload['effective_from']??''));$today=(new DateTimeImmutable('today',new DateTimeZone('America/Mexico_City')))->format('Y-m-d');if($effective<$today)failRequest('La vigencia no puede iniciar antes de hoy.',422);$reason=requiredString($payload,'change_reason','el motivo del cambio',500);$current=findOne($pdo,"SELECT * FROM finished_product_bom_assignments WHERE finished_item_id=:item AND effective_to IS NULL ORDER BY effective_from DESC,id DESC LIMIT 1",['item'=>$item['id']],'El producto no tiene lista de empaque importada.');if($current['assignment_status']==='ACTIVE'){$nextMonday=(new DateTimeImmutable('next monday',new DateTimeZone('America/Mexico_City')))->format('Y-m-d');if($effective<$nextMonday)failRequest('El cambio debe iniciar el próximo lunes o después para no alterar órdenes actuales.',422);}
    $old=findOne($pdo,"SELECT bv.id,bv.bom_id,bv.output_qty,bv.output_uom_id FROM bom_versions bv WHERE bv.id=:id",['id'=>$current['packaging_bom_version_id']],'No se localizó la versión de empaque actual.');$pdo->beginTransaction();try{$version=(int)safeScalar($pdo,"SELECT COALESCE(MAX(version_no),0)+1 FROM bom_versions WHERE bom_id=:bom",['bom'=>$old['bom_id']]);$pdo->prepare("UPDATE bom_versions SET effective_to=CASE WHEN effective_from<:effective_compare THEN DATE_SUB(:effective,INTERVAL 1 DAY) ELSE effective_from END,status='OBSOLETE' WHERE id=:id")->execute(['effective_compare'=>$effective,'effective'=>$effective,'id'=>$old['id']]);$pdo->prepare("INSERT INTO bom_versions (bom_id,version_no,output_qty,output_uom_id,effective_from,status,expected_yield_pct,source_reference,approved_by,approved_at) VALUES (:bom,:version,:output,:uom,:effective,'ACTIVE',100,:source,:user,UTC_TIMESTAMP(6))")->execute(['bom'=>$old['bom_id'],'version'=>$version,'output'=>$old['output_qty'],'uom'=>$old['output_uom_id'],'effective'=>$effective,'source'=>'PACK-CHANGE-'.$item['sku'].'-'.$effective.'-'.substr(hash('sha256',$reason),0,10),'user'=>$user['id']]);$newVersion=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO bom_components (bom_version_id,line_no,component_item_id,component_uom_id,qty_per_output,scrap_pct,is_optional) SELECT :new_version,ROW_NUMBER() OVER (ORDER BY line_no),component_item_id,CASE WHEN component_item_id=:component THEN :new_uom ELSE component_uom_id END,CASE WHEN component_item_id=:component_qty THEN :qty ELSE qty_per_output END,scrap_pct,is_optional FROM bom_components WHERE bom_version_id=:old_version")->execute(['new_version'=>$newVersion,'component'=>$component['id'],'new_uom'=>$component['base_uom_id'],'component_qty'=>$component['id'],'qty'=>$qty,'old_version'=>$old['id']]);if(!safeScalar($pdo,"SELECT COUNT(*) FROM bom_components WHERE bom_version_id=:version AND component_item_id=:component",['version'=>$newVersion,'component'=>$component['id']])){$line=(int)safeScalar($pdo,"SELECT COALESCE(MAX(line_no),0)+1 FROM bom_components WHERE bom_version_id=:version",['version'=>$newVersion]);$pdo->prepare("INSERT INTO bom_components (bom_version_id,line_no,component_item_id,component_uom_id,qty_per_output,scrap_pct,is_optional) VALUES (:version,:line,:component,:uom,:qty,0,0)")->execute(['version'=>$newVersion,'line'=>$line,'component'=>$component['id'],'uom'=>$component['base_uom_id'],'qty'=>$qty]);}
        if($current['assignment_status']!=='ACTIVE'){if($current['effective_from']===$effective)$pdo->prepare("UPDATE finished_product_bom_assignments SET packaging_bom_version_id=:version,change_reason=:reason,created_by=:user WHERE id=:id")->execute(['version'=>$newVersion,'reason'=>$reason,'user'=>$user['id'],'id'=>$current['id']]);else{$pdo->prepare("UPDATE finished_product_bom_assignments SET effective_to=DATE_SUB(:effective,INTERVAL 1 DAY),assignment_status='OBSOLETE' WHERE id=:id")->execute(['effective'=>$effective,'id'=>$current['id']]);$pdo->prepare("INSERT INTO finished_product_bom_assignments (finished_item_id,packaging_bom_version_id,effective_from,assignment_status,change_reason,created_by) VALUES (:item,:version,:effective,'PENDING_FORMULATION',:reason,:user)")->execute(['item'=>$item['id'],'version'=>$newVersion,'effective'=>$effective,'reason'=>$reason,'user'=>$user['id']]);}writeAudit($pdo,(int)$user['id'],'UPDATE','packaging_bom_version',$newVersion,['product'=>$item['sku'],'component'=>$component['sku'],'quantity'=>$qty,'effective_from'=>$effective],$reason);$pdo->commit();return ['id'=>$newVersion,'product'=>$item['name'],'component'=>$component['name'],'requiresFormula'=>true];}
        $formula=(int)$current['oil_formula_version_id'];
        $pdo->commit();
        try{
            $assignment=assignProductFormulaV18($pdo,$user,['finished_item_id'=>$item['id'],'oil_formula_version_id'=>$formula,'packaging_bom_version_id'=>$newVersion,'effective_from'=>$effective,'change_reason'=>$reason]);
        }catch(Throwable $assignmentError){
            $pdo->beginTransaction();
            try{
                $pdo->prepare("DELETE FROM bom_versions WHERE id=:id")->execute(['id'=>$newVersion]);
                $pdo->prepare("UPDATE bom_versions SET effective_to=NULL,status='ACTIVE' WHERE id=:id")->execute(['id'=>$old['id']]);
                $pdo->commit();
            }catch(Throwable $restoreError){
                if($pdo->inTransaction())$pdo->rollBack();
            }
            throw $assignmentError;
        }
        writeAudit($pdo,(int)$user['id'],'UPDATE','packaging_bom_version',$newVersion,['product'=>$item['sku'],'component'=>$component['sku'],'quantity'=>$qty,'effective_from'=>$effective],$reason);
        return ['id'=>$newVersion,'product'=>$item['name'],'component'=>$component['name'],'assignment'=>$assignment];
    }catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();throw $error;}
}

function createPlannedArrivalV18(PDO $pdo,array $user,array $payload): array
{
    requirePermission($pdo,(int)$user['id'],'PLANNED_ARRIVALS','CREATE');$item=findOne($pdo,"SELECT i.id,i.name,i.item_type,i.base_uom_id,w.id AS warehouse_id FROM items i INNER JOIN warehouses w ON w.id=:warehouse AND w.is_active=1 AND w.warehouse_type=CASE WHEN i.item_type IN ('RAW_FRUIT','RAW_OTHER','BULK_OIL') THEN 'RAW_MATERIAL' WHEN i.item_type='PACKAGING' THEN 'PACKAGING' WHEN i.item_type='FINISHED_GOOD' THEN 'FINISHED_GOODS' ELSE 'NONE' END WHERE i.id=:item AND i.is_active=1",['item'=>(int)($payload['item_id']??0),'warehouse'=>(int)($payload['warehouse_id']??0)],'El material y el almacén no corresponden.');$week=validDate((string)($payload['planned_week']??''));if((int)(new DateTimeImmutable($week))->format('N')!==1)failRequest('Selecciona el lunes de la semana planeada.',422);$qty=positiveNumber($payload,'expected_qty','La cantidad esperada');$supplier=(int)($payload['supplier_id']??0)?:null;if($supplier&&!safeScalar($pdo,"SELECT COUNT(*) FROM suppliers WHERE id=:id AND is_active=1",['id'=>$supplier]))failRequest('El proveedor no es válido.',422);$pdo->prepare("INSERT INTO planned_material_arrivals (arrival_number,item_id,warehouse_id,planned_week,expected_qty,uom_id,supplier_id,status,notes,created_by) VALUES (:number,:item,:warehouse,:week,:qty,:uom,:supplier,'PLANNED',:notes,:user)")->execute(['number'=>provisionalNumber('LLP'),'item'=>$item['id'],'warehouse'=>$item['warehouse_id'],'week'=>$week,'qty'=>$qty,'uom'=>$item['base_uom_id'],'supplier'=>$supplier,'notes'=>optionalString($payload,'notes',1000),'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();$number=finalNumber('LLP',$id);$pdo->prepare("UPDATE planned_material_arrivals SET arrival_number=:number WHERE id=:id")->execute(['number'=>$number,'id'=>$id]);writeAudit($pdo,(int)$user['id'],'CREATE','planned_material_arrival',$id,['number'=>$number,'item'=>$item['name'],'week'=>$week,'quantity'=>$qty]);return ['id'=>$id,'number'=>$number];
}

function setInitialInventoryV18(PDO $pdo,array $user,array $payload): array
{
    if(!isSuperAdmin($pdo,(int)$user['id']))failRequest('Solo el administrador del sistema puede habilitar o cerrar la captura inicial.',403);$warehouse=findOne($pdo,"SELECT id,name FROM warehouses WHERE id=:id AND code IN ('MP','EMPAQUE','PT')",['id'=>(int)($payload['warehouse_id']??0)],'Selecciona uno de los tres almacenes principales.');$enabled=filter_var($payload['enabled']??false,FILTER_VALIDATE_BOOLEAN);$pdo->prepare("INSERT INTO warehouse_inventory_settings (warehouse_id,initial_capture_enabled,disabled_at,disabled_by) VALUES (:warehouse,:enabled,:disabled_at,:disabled_by) ON DUPLICATE KEY UPDATE initial_capture_enabled=VALUES(initial_capture_enabled),disabled_at=VALUES(disabled_at),disabled_by=VALUES(disabled_by)")->execute(['warehouse'=>$warehouse['id'],'enabled'=>$enabled?1:0,'disabled_at'=>$enabled?null:gmdate('Y-m-d H:i:s'),'disabled_by'=>$enabled?null:$user['id']]);writeAudit($pdo,(int)$user['id'],'UPDATE','warehouse_inventory_setting',$warehouse['id'],['enabled'=>$enabled]);return ['id'=>(int)$warehouse['id'],'enabled'=>$enabled];
}

function createProductionOrderV18(PDO $pdo,array $user,array $payload): array
{
    $start=validDate(substr((string)($payload['planned_start']??''),0,10));$assignment=findOne($pdo,"SELECT a.id,a.compiled_bom_version_id,a.oil_formula_version_id FROM finished_product_bom_assignments a WHERE a.finished_item_id=:item AND a.assignment_status='ACTIVE' AND a.effective_from<=:start AND (a.effective_to IS NULL OR a.effective_to>=:start_end) ORDER BY a.effective_from DESC LIMIT 1",['item'=>(int)($payload['finished_item_id']??0),'start'=>$start,'start_end'=>$start],'El producto todavía no tiene una formulación de aceite vigente. Asígnala en Listas de materiales.');$payload['bom_version_id']=$assignment['compiled_bom_version_id'];$result=createProductionOrderV14($pdo,$user,$payload);$pdo->prepare("UPDATE production_orders SET bom_assignment_id=:assignment,oil_formula_version_id=:formula WHERE id=:id")->execute(['assignment'=>$assignment['id'],'formula'=>$assignment['oil_formula_version_id'],'id'=>$result['id']]);return $result;
}

function createProductionCompletionV18(PDO $pdo,array $user,array $payload,array $config): array
{
    $result=createProductionCompletionV14($pdo,$user,$payload);
    if(empty($result['qualityRequest']))return $result;
    $qualityId=(int)safeScalar($pdo,"SELECT id FROM quality_requests WHERE request_number=:number",['number'=>$result['qualityRequest']]);
    $recipients=roleRecipientsV15($pdo,['AREA_ADMIN','AREA_MANAGER','APPROVER'],'CALIDAD');
    $message="{$result['qualityRequest']}: producto terminado {$result['number']}, lote {$result['lot']}. La existencia permanece en WID hasta registrar el dictamen.";
    try{createAlertV15($pdo,'CALIDAD',$recipients,'QUALITY_REQUESTED','WARNING','Producto terminado pendiente de Calidad',$message,'quality_request',$qualityId,'QUALITY_REQUESTED_PRODUCTION_'.$result['id']);queueNotifications($pdo,$config,'QUALITY_REQUESTED','production_completion',(int)$result['id'],$recipients,"Nueva solicitud de Calidad {$result['qualityRequest']}",$message);}catch(Throwable $ignored){}
    return $result;
}

function rebuildWeeklyForecastV18(PDO $pdo,int $forecastVersionId): int
{
    if(!tableExistsV18($pdo,'forecast_weekly_lines'))return 0;$pdo->prepare("DELETE FROM forecast_weekly_lines WHERE forecast_version_id=:version")->execute(['version'=>$forecastVersionId]);$monthly=safeRows($pdo,"SELECT finished_item_id,period_start,forecast_qty,id FROM forecast_lines WHERE forecast_version_id=:version ORDER BY period_start,finished_item_id",['version'=>$forecastVersionId]);$insert=$pdo->prepare("INSERT INTO forecast_weekly_lines (forecast_version_id,finished_item_id,week_start,forecast_qty,allocation_method,source_month,source_row) VALUES (:version,:item,:week,:qty,'WORKDAYS',:month,:source)");$count=0;foreach($monthly as $row){$start=new DateTimeImmutable((string)$row['period_start']);$month=(int)$start->format('n');$days=(int)$start->format('t');$byWeek=[];for($day=1;$day<=$days;$day++){$date=$start->setDate((int)$start->format('Y'),$month,$day);if((int)$date->format('N')>5)continue;$monday=$date->modify('monday this week')->format('Y-m-d');$byWeek[$monday]=($byWeek[$monday]??0)+1;}$totalDays=array_sum($byWeek);$remaining=(float)$row['forecast_qty'];$index=0;$last=count($byWeek)-1;foreach($byWeek as $week=>$workdays){$qty=$index===$last?$remaining:round((float)$row['forecast_qty']*$workdays/$totalDays,6);$remaining-=$qty;if($qty>0){$insert->execute(['version'=>$forecastVersionId,'item'=>$row['finished_item_id'],'week'=>$week,'qty'=>$qty,'month'=>$month,'source'=>$row['id']]);$count++;}$index++;}}return $count;
}
